// Independent pure DTO counterexamples. Uses actual fixed public Core/C2 with
// the explicitly synthetic committed capture setup. No native/decoder authority.
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
import * as C from './source/candidates/tile-authoring/core/c2/index.js';
