const out=path.dirname(fileURLToPath(import.meta.url)),rows=[],sha=b=>createHash('sha256').update(b).digest('hex');
const initial=stageFixture(),x=stageFixture(paintOperations(initial.f)),p=C.planTileAuthoring(T,x.input);assert.equal(p.ok,true,JSON.stringify(p));
const bind=(x,p,c)=>C.bindTileAuthoringTarget(T,{before:x.input.document,plan:p,prepared:null,appearanceCapture:c});
function rec(name,x,p,c,explanation){const r=bind(x,p,c),file=name+'.json',data={fixed:'f32f02a57d445b393b9fc96a8d757f1947a6f46a',scope:'Pure fixed Core/C2, synthetic DTO capture control only',input:x.input,plan:p,appearanceCapture:c,response:r};const bytes=JSON.stringify(data,null,2)+'\n';fs.writeFileSync(path.join(out,file),bytes);rows.push({name,accepted:r.ok,diagnostics:r.diagnostics??null,costBounds:r.costBounds??null,explanation,file,sha256:sha(bytes)});}
const base=preparedCapture(p);assert.equal(bind(x,p,base).ok,true,'Positive fixed fixture');
function twoSteps(c,first,last){ledger(first);ledger(last);c.ledgerTrace=[{eventId:'review.acquire',action:'acquire',ownerRequestId:p.original.requestId,ledger:first},{eventId:'review.admit',action:'admit',ownerRequestId:p.original.requestId,ledger:last}];c.admittedGeometry=cp(last.geometry);c.peakTotals=Object.fromEntries(Object.keys(first.totals).map(k=>[k,Math.max(p.sourceCapture.ledger.totals[k],first.totals[k],last.totals[k])]));Object.assign(c.costBounds,last.totals);}
{const c=preparedCapture(p),first=cp(c.ledgerTrace[0].ledger);first.allocations.push(allocation('review.owned.scratch','decoder-scratch','decoded-additional',1000000,p.original.requestId,{sampledAtlas:false}));const last=cp(first);last.sequence++;last.allocations.at(-1).chargedBytes=1;twoSteps(c,first,last);rec('owned-live-charge-shrink',x,p,c,'An owned still-live scratch allocation falls1000000→1 byte with same physical identity and no retirement receipt. The row remains live and referenced.');}
{const c=preparedCapture(p),first=cp(c.ledgerTrace[0].ledger);first.materials.push({materialId:'review.owned.cached.material',state:'cache-idle',ownerRequestId:p.original.requestId,referenceIds:[],retirementReceiptDigest:null});const last=cp(first);last.sequence++;last.materials.pop();twoSteps(c,first,last);rec('owned-material-disappears',x,p,c,'A new request-owned cache-idle material vanishes between acquire/admit with no retained retired-verified row or positive receipt.');}
{const before=p.targetDocument,mark=cp(before.authoring.decorations.chunks[0].marks[0]);mark.revision++;mark.graphic.opacity=.5;const y=stageFixture([{kind:'decoration.update',body:{markId:mark.id,expectedRevision:1,replacement:mark,groupPolicy:'preserve-whole-group'}}],{document:before,requestId:'review.source.residency'}),q=C.planTileAuthoring(T,y.input);assert.equal(q.ok,true,JSON.stringify(q));const c=preparedCapture(q),l=c.ledgerTrace[0].ledger;assert.equal(q.sourceCapture.ledger.residency.length,1);l.residency=l.residency.filter(row=>row.viewId!=='fixture.accepted');ledger(l);c.admittedGeometry=cp(l.geometry);c.peakTotals=Object.fromEntries(Object.keys(l.totals).map(k=>[k,Math.max(q.sourceCapture.ledger.totals[k],l.totals[k])]));Object.assign(c.costBounds,l.totals);rec('accepted-source-residency-disappears',y,q,c,'The accepted source root/native IDs remain live and identical, but its existing mark residency vanishes; only the full candidate copy remains charged,1instead of2 resident mark records.');}
{const c=preparedCapture(p),l=c.ledgerTrace[0].ledger,blob=p.resourceRequirements.encodedNeeds.find(x=>x.blob.sha256===p.resourceRequirements.decodeNeeds[0].blobSha256).blob;l.allocations.push(allocation('review.extra.full-page-copy','artwork-image','decoded-additional',1024,p.original.requestId,{blobSha256:blob.sha256}));ledger(l);c.admittedGeometry=cp(l.geometry);c.peakTotals=cp(l.totals);Object.assign(c.costBounds,l.totals);rec('extra-sampled-page-under-rgba-bound',x,p,c,'An extra sampled GPU artwork image tied to the full immutable1536×1024page is charged1024bytes instead of6291456, because it is not named by decodedObservations.allocationIds. Existing committed4-page positive test uses the same loophole.');}
const result={version:1,fixed:'f32f02a57d445b393b9fc96a8d757f1947a6f46a',scope:'Independent data/consistency falsifiers using labelled synthetic committed captures; no renderer/Host/decoder proof',positiveBaselineAccepted:true,rows};fs.writeFileSync(path.join(out,'ledger-counterexamples.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(rows.map(({name,accepted,diagnostics})=>({name,accepted,diagnostics}))));
